/**
 * Per-weapon pose animation sets and attack visuals (attack animation, cast and hit spotanims,
 * projectile), with the attack-animation name table.
 *
 * Sources:
 *   - geheur/weapon-animation-replacer data.json
 *   - runelite/runelite SpotanimID.java
 *   - OreoCupcakes/kotori-plugins PlayerAttackAnimations.java
 *
 * Converted from those sources at the revisions THIRD_PARTY_NOTICES.md pins. No generator for it is
 * part of this repository: the file is maintained by hand here.
 */

/** Full pose/movement animation set for a weapon */
export interface WeaponAnimationSetFull {
  idle: number;
  walk: number;
  run: number;
  walkBack: number;
  turnLeft: number;
  turnRight: number;
  turn180: number;
  shuffle: number;
  attackStyle1: number;
  attackStyle2: number;
  attackStyle3: number;
  attackStyle4: number;
  defend: number;
  mainAttack: number; // index 14: used by ranged/magic for primary attack
}

/** Combat visual data for a weapon's attack */
export interface WeaponCombatVisuals {
  /** The attack animation played on the player (seq ID) */
  attackAnimation: number;
  /** Spotanim played on the caster at cast time */
  castSpotanim: number;
  castSpotanimHeight: number;
  /** Projectile spotanim that travels to target */
  projectileId: number;
  projectileStartHeight: number;
  projectileEndHeight: number;
  projectileSlope: number;
  projectileStartDelay: number; // startMovement field
  /** Spotanim played on the target on hit */
  hitSpotanim: number;
  hitSpotanimHeight: number;
  /** Source name from data.json for reference */
  sourceName?: string;
}

